const client = msg.metadata.source;

// Dot-notasjon: global.get("parat_bridge.base_urls.wasos") returnerer
// undefined i stedet for TypeError hvis parat_bridge er null ved oppstart.

msg.headers = { "x-api-key": client.client_specific.api.key };
msg.url = global.get("parat_bridge.base_urls.wasos")
    + "/api/chat/messages/" + client.client_specific.chatroom_name + "?limit=50";

return msg;
